<?php
require __DIR__.'/../api/life/store.php';require __DIR__.'/../api/life/reminders.php';
$db=new PDO('sqlite::memory:');$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$db->exec(file_get_contents(__DIR__.'/../api/life/schema.sql'));$s=new LifeStore($db);$s->initialize('reminder-test-long-password');$b=$s->read();$list=$b['state']['lists'][0]['id'];$n=0;
function ok($v,$m){global $n;if(!$v)throw new RuntimeException($m);$n++;}
function bad($f){try{$f();}catch(LifeError){ok(true,'rejection');return;}throw new RuntimeException('Expected rejection');}
$args=['title'=>'Reminder test','listId'=>$list,'dueDate'=>'2026-10-15','dueTime'=>'09:00','reminderMinutes'=>15,'notes'=>'Hello','notesDelta'=>['ops'=>[['insert'=>'Hello','attributes'=>['bold'=>true]],['insert'=>"\n"]]]];
$b=$s->mutate($b['version'],'task.save',$args);$t=end($b['state']['tasks']);ok($t['notesDelta']['ops'][0]['attributes']['bold'],'format saved');ok(life_task_reminder($t)===strtotime('2026-10-15T07:45:00Z'),'Lagos reminder offset');
$at=life_task_reminder($t);ok(count(LifeReminders::due($b['state'],$at-1))===0,'not early');ok(count(LifeReminders::due($b['state'],$at))===1,'due');$done=$b['state'];$done['tasks'][0]['listId']=$done['lists'][5]['id'];ok(!LifeReminders::due($done,$at),'done excluded');$done['tasks'][0]['archived']=true;ok(!LifeReminders::due($done,$at),'archived excluded');ok(!LifeReminders::due($b['state'],$at+86401),'expired excluded');
foreach([['dueTime'=>'24:00'],['reminderMinutes'=>7],['notesDelta'=>['ops'=>[['insert'=>'Hello','attributes'=>['link'=>'javascript:alert(1)']]]]],['notesDelta'=>['ops'=>[['insert'=>['image'=>'https://bad.test']]]]],['notesDelta'=>['ops'=>[['insert'=>'Wrong']]]]] as $patch)bad(fn()=>$s->mutate($b['version'],'task.save',array_merge($args,['id'=>$t['id']],$patch)));
$b=$s->mutate($b['version'],'task.save',array_merge($args,['id'=>$t['id'],'dueDate'=>'','dueTime'=>'','reminderMinutes'=>null]));ok(end($b['state']['tasks'])['reminderMinutes']===null,'reminder removed');
$r=new LifeReminders($s);bad(fn()=>LifeReminders::endpoint('http://127.0.0.1'));bad(fn()=>LifeReminders::endpoint('https://evil.test'));bad(fn()=>LifeReminders::endpoint('https://fcm.googleapis.com:443/x'));ok(LifeReminders::endpoint('https://fcm.googleapis.com/fcm/send/test')!=='','approved endpoint');
$sub=['endpoint'=>'https://fcm.googleapis.com/fcm/send/test','keys'=>['p256dh'=>str_repeat('A',87),'auth'=>str_repeat('A',22)]];$r->subscribe($sub);$r->subscribe($sub);ok((int)$db->query('SELECT COUNT(*) FROM life_push_subscriptions')->fetchColumn()===1,'idempotent subscription');$r->unsubscribe($sub['endpoint']);ok((int)$db->query('SELECT COUNT(*) FROM life_push_subscriptions')->fetchColumn()===0,'unsubscribe');echo "$n reminder/editor checks passed\n";
